import { calculateReadingTime, articleMapper } from '../../app/routes/article/article.mapper';

describe('calculateReadingTime', () => {

  test('should return 1 for null body', () => {
    const result = calculateReadingTime(null);
    expect(result).toBe(1);
  });

  test('should return 1 for undefined body', () => {
    const result = calculateReadingTime(undefined);
    expect(result).toBe(1);
  });

  test('should return 1 for empty string body', () => {
    const result = calculateReadingTime('');
    expect(result).toBe(1);
  });

  test('should return 1 for whitespace-only body', () => {
    const result = calculateReadingTime('   \n\t  ');
    expect(result).toBe(1);
  });

  test('should return 1 for body with exactly 200 words', () => {
    const words = Array(200).fill('word').join(' ');
    const result = calculateReadingTime(words);
    expect(result).toBe(1);
  });

  test('should return 2 for body with 201 words', () => {
    const words = Array(201).fill('word').join(' ');
    const result = calculateReadingTime(words);
    expect(result).toBe(2);
  });

  test('should return 3 for body with 500 words', () => {
    const words = Array(500).fill('word').join(' ');
    const result = calculateReadingTime(words);
    expect(result).toBe(3); // Math.ceil(500/200) = 3
  });

  test('should return 1 for body with 50 words', () => {
    const words = Array(50).fill('word').join(' ');
    const result = calculateReadingTime(words);
    expect(result).toBe(1); // Math.max(1, Math.ceil(50/200)) = 1
  });

  test('should handle multiple spaces between words correctly', () => {
    const body = 'word1   word2     word3';
    const result = calculateReadingTime(body);
    expect(result).toBe(1); // 3 words, minimum is 1
  });

  test('should filter out empty strings from word array', () => {
    const body = 'word1  \n\n  word2';
    const result = calculateReadingTime(body);
    expect(result).toBe(1); // 2 words
  });

  test('should return 5 for body with 1000 words', () => {
    const words = Array(1000).fill('word').join(' ');
    const result = calculateReadingTime(words);
    expect(result).toBe(5); // Math.ceil(1000/200) = 5
  });
});

